en.langCss:
:root { --display: "Noto Sans", "Noto Sans TC", sans-serif; --serif: "Noto Serif", "Noto Serif TC", serif; }
.notes dt { letter-spacing: .02em; }
@media (min-width: 521px) { .notes { grid-template-columns: max-content minmax(0, 1fr); } }
@media (max-width: 520px) { .seg[aria-labelledby=catLabel] { grid-auto-flow: row; grid-template-columns: repeat(3, minmax(0, 1fr)); overflow: hidden; } .seg[aria-labelledby=catLabel] span { border-bottom: 2px solid var(--ink); margin-bottom: -2px; } .seg[aria-labelledby=catLabel] label:nth-child(3n) span { border-right: 0; } }
